import {readFileSync,writeFileSync,existsSync,unlinkSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {spawn} from 'node:child_process';
import {resolve,join} from 'node:path';
import {runHeavyGate} from '/Users/ilyagulya/Projects/My/bend/evals/heavy_gate.ts';
const prefix='/tmp/native54-cpu-20261023',reportPath=prefix+'.compile.json';
const hash=p=>createHash('sha256').update(readFileSync(p)).digest('hex');
const json=p=>JSON.parse(readFileSync(p));
const save=(p,v)=>writeFileSync(p,JSON.stringify(v,null,2)+'\n',{flag:'wx'});
const settings={memoryMiB:8192,rssMiB:8192,pollMs:10,timeoutMs:300000,label:'Native54 phase-sampled full compile'};
if(process.argv.includes('--worker')){
 const old=json('checkpoints/native-compiler-v54-compile.json'),build=json(old.build),corpus=json(old.corpus);
 const command=[...old.command];command[command.length-1]=prefix+'.output.mjs';
 if(existsSync(command.at(-1)))throw Error('Output already exists');
 const verify=()=>{
  for(const [p,h] of Object.entries({...build.protectedPins,...build.loadedInputs,...old.protectedPins}))if(hash(p)!==h)throw Error('Pin drift '+p);
  if(hash(build.artifact)!=='14ba401df39b134a1936c8ca92bfb912386f01598ea55c76e0df096cab1f0dad'||hash(build.cPath)!=='3c9be7ea6e71635febc79c09a8695d90907412343f6de32a65afdda8d5f2ef13')throw Error('Binary/C drift');
  if(corpus.files.length!==50||corpus.files.filter(x=>!x.external).length!==15)throw Error('Corpus cardinality');
  for(const row of corpus.files)if(hash(resolve(corpus.directory,row.path))!==row.sha256)throw Error('Corpus drift '+row.path);
  const runtime=corpus.files.map(row=>[row.external?'E':'B',row.namespace??'',resolve(corpus.directory,row.path)].join('\t')).join('\n')+'\n';
  if(readFileSync(command[8],'utf8')!==runtime||readFileSync(command[9],'utf8')!==old.exports.join('\n')+'\n'||old.exports.length!==7720)throw Error('Runtime/export manifest drift');
 };
 verify();
 const phases=[],boundaries=[],fuel=[],begins=[],results=[],samples=[],sampleJobs=[];
 const start=performance.now(),wallStart=new Date().toISOString();
 const child=spawn(command[0],command.slice(1),{stdio:['ignore','pipe','pipe']});
 const profile=phase=>{
  const argv=['/usr/bin/sample',String(child.pid),'10','1','-mayDie','-file',prefix+'.'+phase+'.sample.txt'];
  const row={phase,command:argv,targetPid:child.pid,requestedDurationSeconds:10,samplingIntervalMs:1,startElapsedMs:performance.now()-start,startWall:new Date().toISOString()};samples.push(row);
  const p=spawn(argv[0],argv.slice(1),{stdio:['ignore','pipe','pipe']});let out='',err='';
  p.stdout.on('data',x=>out+=x);p.stderr.on('data',x=>err+=x);
  sampleJobs.push(new Promise((yes,no)=>{p.once('error',no);p.once('close',(code,signal)=>{Object.assign(row,{exitCode:code,signal,endElapsedMs:performance.now()-start,endWall:new Date().toISOString(),stdout:out,stderr:err});writeFileSync(prefix+'.'+phase+'.sample.log',out+err,{flag:'wx'});yes();});}));
 };
 const consume=line=>{
  if(line.startsWith('NATIVE_PHASE ')){const r=JSON.parse(line.slice(13));phases.push(r);boundaries.push({...r,observedElapsedMs:performance.now()-start,observedWall:new Date().toISOString()});if(r.phase==='expand')profile('check');if(r.phase==='check')profile('emit');}
  if(line.startsWith('NATIVE_FUEL '))fuel.push(JSON.parse(line.slice(12)));
  if(line.startsWith('NATIVE_BEGIN '))begins.push(JSON.parse(line.slice(13)));
  if(line.startsWith('NATIVE_RESULT '))results.push(JSON.parse(line.slice(14)));
 };
 let stdout='',stderr='',pendingOut='',pendingErr='';
 child.stdout.on('data',x=>{stdout+=x;pendingOut+=x;let i;while((i=pendingOut.indexOf('\n'))>=0){consume(pendingOut.slice(0,i));pendingOut=pendingOut.slice(i+1);}});
 child.stderr.on('data',x=>{stderr+=x;pendingErr+=x;let i;while((i=pendingErr.indexOf('\n'))>=0){consume(pendingErr.slice(0,i));pendingErr=pendingErr.slice(i+1);}});
 const exit=await new Promise((yes,no)=>{child.once('error',no);child.once('close',(code,signal)=>yes({code,signal}));});
 const elapsedMs=performance.now()-start;
 await Promise.all(sampleJobs);
 writeFileSync(prefix+'.stdout.log',stdout,{flag:'wx'});writeFileSync(prefix+'.stderr.log',stderr,{flag:'wx'});
 verify();
 if(exit.code!==0||begins.length!==1||begins[0].computeThreads!==1||results.length!==1||results[0].modules!==15||results[0].result!=='EmitSuccess'||fuel.length!==15||fuel.some(x=>x.cells!==8000000)||JSON.stringify(phases.map(x=>x.phase))!==JSON.stringify(['parse','expand','check','emit']))throw Error('Incomplete native run');
 if(hash(command.at(-1))!=='a1033733403dddb6214b6433ec55cd385fc210ce0d985871259a25487bd06d29'||readFileSync(command.at(-1)).length!==20281365)throw Error('Output mismatch');
 save(reportPath,{status:'NATIVE_FULL_COMPILE_PASS',command,nativePid:child.pid,wallStart,elapsedMs,exit,phases,boundaries,fuel,result:results[0],exports:old.exports,output:command.at(-1),outputSha256:hash(command.at(-1)),outputBytes:20281365,samples,sourcePinsVerifiedBeforeAfter:true,corpusFiles:50,baselineReportSha256:hash('checkpoints/native-compiler-v54-compile.json'),buildReportSha256:hash(old.build),runtimeManifestSha256:hash(command[8]),exportManifestSha256:hash(command[9])});
}else{
 const guardian=await runHeavyGate([process.execPath,'--smol','/tmp/native54-cpu-20261023.mjs','--worker'],settings);
 if(guardian.status!=='PASS')throw Error('Compile gate '+JSON.stringify(guardian));
 const result=json(reportPath);result.guardian=guardian;writeFileSync(reportPath,JSON.stringify(result,null,2)+'\n');
 const smokeGuardian=await runHeavyGate(['node','--max-old-space-size=3072','/tmp/native54-cpu-20261023.smoke.mjs'],{...settings,label:'Native54 profiled output actual import smoke'});
 save(prefix+'.gates.json',{guardian,smokeGuardian});
 if(smokeGuardian.status!=='PASS')throw Error('Smoke gate failed');
 unlinkSync(result.output);
 save(prefix+'.cleanup.json',{removedOnlyOwnOutput:result.output,sha256:result.outputSha256,bytes:result.outputBytes,afterActualImportProof:true});
 console.log(JSON.stringify({status:'PROFILE_COMPILE_AND_SMOKE_PASS',reportPath,guardian,smokeGuardian,samples:result.samples}));
}

