import{readFileSync,writeFileSync}from'node:fs';
import{createHash}from'node:crypto';
import{resolve}from'node:path';
import{pathToFileURL}from'node:url';
const hash=p=>createHash('sha256').update(readFileSync(p)).digest('hex');
const reportPath=resolve('/tmp/native54-cpu-20261023.compile.json');
const report=JSON.parse(readFileSync(reportPath));
if(report.status!=='NATIVE_FULL_COMPILE_PASS'||report.guardian?.status!=='PASS'||report.exports.length!==7720||report.result.modules!==15)throw Error('Missing complete native result');
const expected='a1033733403dddb6214b6433ec55cd385fc210ce0d985871259a25487bd06d29';
if(hash(report.output)!==expected||report.outputSha256!==expected||report.outputBytes!==20281365)throw Error('Native full output differs from exact frozen Mac output');
const runtimePath=resolve('checkpoints/compiler-benchmark-v41-step-runtime.mjs');
if(hash(runtimePath)!=='2cad05bb4885854d7ede65336dbe287ac78063f8321110d2d63018e9890000fd')throw Error('Frozen output ABI drift');
const api=(await import(pathToFileURL(report.output).href)).default;
const actual=Object.keys(api);if(actual.length!==report.exports.length||actual.some((name,i)=>name!==report.exports[i]))throw Error('Public export order/set mismatch');
const tag=x=>typeof x?.$==='string'?x.$.split('.').at(-1):undefined;
const end=Object.freeze({$:'FeedbackFuelEnd'}),prototype={get tail(){return fuel(this.remaining-1);}};
function fuel(n){if(!n)return end;const x=Object.create(prototype);x.$='FeedbackFuelCell';x.remaining=n;return x;}
const parsed=api.parse_with_fuel(fuel(8000000),'/native-output-smoke.bend','type Bit is Data:\n  Zero{}\n  One{}\n\ndef main() -> Bit:\n  One{}\n');
if(tag(parsed)!=='FeedbackComplete'||tag(parsed.value?.result)!=='ParseSuccess')throw Error('Emitted parser failed actual source');
let defs=parsed.value.result.module.declarations,main=false;while(tag(defs)==='Con'){if(tag(defs.head)==='DefTop'&&defs.head.definition.key==='main')main=true;defs=defs.tail;}if(tag(defs)!=='Nil'||!main)throw Error('Emitted parser lost declaration');
const runtime=await import(pathToFileURL(runtimePath).href),checked=runtime.runCheckerSteps(api,{$:'Nil'});
if(tag(checked)!=='CheckSuccess'||tag(checked.modules)!=='Nil')throw Error('Emitted checker failed empty-module semantics');
const proof={status:'NATIVE_FULL_COMPILE_EXACT_OUTPUT_AND_IMPORT_SMOKE_PASS',nativeReport:reportPath,nativeReportSha256:hash(reportPath),outputSha256:expected,outputBytes:report.outputBytes,exports:actual.length,modules:report.result.modules,emittedParserActualSource:true,emittedCheckerEmptyModules:true,outputSmokeRuntimeSha256:hash(runtimePath),runtime:process.versions,checksExcluded:0,outputPatches:0,nativeBinaryBootstrap:false};
writeFileSync('/tmp/native54-cpu-20261023.smoke.json',JSON.stringify(proof,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(proof));
